  { r: 'aflutter', hr: 150, p: true, g: 'fastn', ctx: '\u05de\u05ea\u05d1\u05d2\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05e0\u05d9\u05ea\u05d5\u05d7 \u05dc\u05d1, \u05d9\u05e6\u05d9\u05d1', a: '\u05e8\u05e4\u05e8\u05d5\u05e3 \u05e4\u05e8\u05d5\u05d6\u05d3\u05d5\u05e8\u05d9\u05dd', f: '\u05d2\u05dc\u05d9 \u05e8\u05e4\u05e8\u05d5\u05e3 \u05d1\u05e6\u05d5\u05e8\u05ea \u05e9\u05d9\u05e0\u05d9 \u05de\u05e1\u05d5\u05e8.', nx: { q: '\u05d9\u05e6\u05d9\u05d1. \u05de\u05d4 \u05e2\u05db\u05e9\u05d9\u05d5?', ok: '\u05d9\u05d9\u05e2\u05d5\u05e5 \u05e7\u05e8\u05d3\u05d9\u05d5\u05dc\u05d5\u05d2\u05d9; \u05e0\u05d9\u05d8\u05d5\u05e8 ECG \u05e8\u05e6\u05d9\u05e3', bad: ['\u05e9\u05d5\u05e7 \u05dc\u05d0 \u05de\u05e1\u05d5\u05e0\u05db\u05e8\u05df 2 J/kg \u05e2\u05db\u05e9\u05d9\u05d5', '\u05d0\u05d8\u05e8\u05d5\u05e4\u05d9\u05df 0.02 mg/kg \u05dc\u05e9\u05d9\u05e4\u05d5\u05e8 \u05d4\u05d4\u05d5\u05dc\u05db\u05d4', '\u05d0\u05de\u05d9\u05d5\u05d3\u05e8\u05d5\u05df \u05d5\u05e4\u05e8\u05d5\u05e7\u05d0\u05d9\u05e0\u05d0\u05de\u05d9\u05d3 \u05d9\u05d7\u05d3'] } },
  { r: 'afib', hr: 130, p: true, g: 'fastn', ctx: '\u05de\u05ea\u05d1\u05d2\u05e8, \u05d3\u05e4\u05d9\u05e7\u05d5\u05ea \u05dc\u05d1, \u05d9\u05e6\u05d9\u05d1', a: '\u05e4\u05e8\u05e4\u05d5\u05e8 \u05e4\u05e8\u05d5\u05d6\u05d3\u05d5\u05e8\u05d9\u05dd', f: '\u05d0\u05d9-\u05e1\u05d3\u05d9\u05e8\u05d5\u05ea \u05de\u05d5\u05d7\u05dc\u05d8\u05ea (irregularly irregular), \u05d0\u05d9\u05df \u05d2\u05dc\u05d9 P.', nx: { q: '\u05d9\u05e6\u05d9\u05d1. \u05de\u05d4 \u05e2\u05db\u05e9\u05d9\u05d5?', ok: '\u05d9\u05d9\u05e2\u05d5\u05e5 \u05e7\u05e8\u05d3\u05d9\u05d5\u05dc\u05d5\u05d2\u05d9; \u05d1\u05d3\u05d9\u05e7\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05dc\u05d9\u05d8\u05d9\u05dd', bad: ['\u05e9\u05d5\u05e7 \u05dc\u05d0 \u05de\u05e1\u05d5\u05e0\u05db\u05e8\u05df 2 J/kg \u05e2\u05db\u05e9\u05d9\u05d5', '\u05d0\u05d3\u05e0\u05d5\u05d6\u05d9\u05df 0.2 mg/kg \u05d1\u05d3\u05d7\u05d9\u05e4\u05d4 \u05dc\u05d4\u05de\u05e8\u05ea \u05d4\u05e7\u05e6\u05d1', '\u05e4\u05e2\u05d5\u05dc\u05d4 \u05d5\u05d2\u05d0\u05dc\u05d9\u05ea, \u05d5\u05d0\u05d6 ECG \u05d7\u05d5\u05d6\u05e8'] } },
  { r: 'torsades', hr: 0, p: false, g: 'wide', ctx: '\u05e8\u05e7\u05e2 \u05e9\u05dc QT \u05d0\u05e8\u05d5\u05da, \u05e7\u05e8\u05e1, \u05d0\u05d9\u05df \u05d3\u05d5\u05e4\u05e7', a: '\u05d8\u05d5\u05e8\u05e1\u05d0\u05d3 \u05d3\u05d4 \u05e4\u05d5\u05d0\u05e0\u05d8', f: 'VT \u05e4\u05d5\u05dc\u05d9\u05de\u05d5\u05e8\u05e4\u05d9 \u05e9\u05de\u05ea\u05e4\u05ea\u05dc \u05e1\u05d1\u05d9\u05d1 \u05e7\u05d5 \u05d4\u05d1\u05e1\u05d9\u05e1.', nx: { q: '\u05d0\u05d9\u05df \u05d3\u05d5\u05e4\u05e7. \u05de\u05d4 \u05e2\u05db\u05e9\u05d9\u05d5?', ok: '\u05e9\u05d5\u05e7 2 J/kg, CPR; \u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd 20\u201350 mg/kg', bad: ['\u05e7\u05e8\u05d3\u05d9\u05d5\u05d5\u05e8\u05e1\u05d9\u05d4 \u05de\u05e1\u05d5\u05e0\u05db\u05e8\u05e0\u05ea, \u05d5\u05d0\u05d6 \u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd \u05e1\u05d5\u05dc\u05e4\u05d8', '\u05e9\u05d5\u05e7 2 J/kg, CPR; \u05e7\u05dc\u05e6\u05d9\u05d5\u05dd \u05db\u05dc\u05d5\u05e8\u05d9\u05d3 20 mg/kg', '\u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd \u05e1\u05d5\u05dc\u05e4\u05d8 20\u201350 mg/kg IV, \u05d5\u05d0\u05d6 CPR'] } }
